{"src/runTasks.mjs":"/**
 * tasks是无参数异步函数数组，concurrency是并发上限；返回Promise。
 * 按输入顺序返回结果；任一任务失败则整体reject（首个失败原因），
 * 但不会中断已在运行的任务，且不再启动新任务。
 */
export function runTasks(tasks, concurrency) {
  return new Promise((resolve, reject) => {
    if (!Array.isArray(tasks)) {
      reject(new TypeError('tasks must be an array of functions'));
      return;
    }

    const total = tasks.length;
    if (total === 0) {
      resolve([]);
      return;
    }

    for (let i = 0; i < total; i++) {
      if (typeof tasks[i] !== 'function') {
        reject(new TypeError(`tasks[${i}] must be a function`));
        return;
      }
    }

    let limit = Math.floor(Number(concurrency));
    if (!Number.isFinite(limit) || limit < 1) {
      limit = 1;
    }
    if (limit > total) {
      limit = total;
    }

    const results = new Array(total);
    let nextIndex = 0;
    let active = 0;
    let settled = false;

    const launch = () => {
      if (settled) {
        return;
      }
      while (active < limit && nextIndex < total) {
        const index = nextIndex++;
        active++;
        let promise;
        try {
          promise = Promise.resolve(tasks[index]());
        } catch (error) {
          promise = Promise.reject(error);
        }
        promise.then(
          value => {
            if (settled) {
              return;
            }
            results[index] = value;
            active--;
            if (nextIndex >= total && active === 0) {
              settled = true;
              resolve(results);
            } else {
              launch();
            }
          },
          error => {
            if (settled) {
              return;
            }
            settled = true;
            reject(error);
          }
        );
      }
    };

    launch();
  });
}
